SELECT COUNT(*) FROM postHistory as ph, comments as c, posts as p, users as u WHERE u.Id = c.UserId AND u.Id = p.OwnerUserId AND u.Id = ph.UserId AND ph.CreationDate<=CAST('2014-08-18 08:54:12' AS TIMESTAMP) AND c.Score=0 AND p.Score>=-2 AND p.CommentCount>=0 AND p.CommentCount<=12 AND p.FavoriteCount>=0 AND p.FavoriteCount<=6
